using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 // Cosmetic only: follows the real action after layout; never dispatches input or grants progress.
 [RequireComponent(typeof(CanvasRenderer))]
 public sealed class TutorialPointer:MaskableGraphic {
  GameRuntime game;GameMenu menu;RectTransform target;string signature;Vector2 rest;readonly Vector3[] corners=new Vector3[4];
  public void Initialize(GameRuntime runtime){game=runtime;menu=game.GetComponent<GameMenu>();raycastTarget=false;rectTransform.sizeDelta=new Vector2(32,40);gameObject.AddComponent<LayoutElement>().ignoreLayout=true;}
  protected override void OnEnable(){base.OnEnable();Canvas.willRenderCanvases+=Place;}protected override void OnDisable(){Canvas.willRenderCanvases-=Place;base.OnDisable();}
  void Place(){if(game?.State==null)return;var s=game.State;bool active=s.Story.tutorial=="active"&&game.CurrentTab!="story"&&!(menu?.IsOpen??false)&&!(game.WorkshopView!=null&&game.WorkshopView.DetailRoot.activeInHierarchy);if(!active){canvasRenderer.SetAlpha(0);signature=null;return;}string key=s.Story.target+"|"+s.Story.open+"|"+game.CurrentTab+"|"+s.Retention.aiName;
   if(key!=signature||target==null||!target.gameObject.activeInHierarchy){signature=key;string id=string.IsNullOrEmpty(s.Retention.aiName)?"StoryNameInput":s.Story.open!=null?"StoryContinue":TutorialNavigation.Quote(s)?.Element;var obj=id==null?null:GameObject.Find(id);if(obj!=null&&obj.GetComponent<LearningCard>()!=null)obj=obj.GetComponent<LearningCard>().StartAction.gameObject;if(obj!=null&&obj.GetComponent<HardwarePresentation>()!=null)obj=obj.transform.Find("PurchaseCost/HardwarePurchase").gameObject;target=obj==null?null:(RectTransform)obj.transform;
    if(target==null&&(string.IsNullOrEmpty(s.Retention.aiName)||s.Story.open!=null)){signature=null;canvasRenderer.SetAlpha(0);return;}
    if(target==null){var q=TutorialNavigation.Quote(s);var b=q?.Tab=="training"?game.TrainingTab:q?.Tab=="research"?game.ResearchTab:q?.Tab=="items"?game.ItemsTab:q?.Tab=="prestige"?game.PrestigeTab:game.HardwareTab;target=(RectTransform)b.transform;}}
   target.GetWorldCorners(corners);var point=Vector3.Lerp(corners[0],corners[3],.8f)+Vector3.Lerp(Vector3.zero,corners[1]-corners[0],.12f);var scroll=target.GetComponentInParent<ScrollRect>();if(scroll!=null&&!RectTransformUtility.RectangleContainsScreenPoint(scroll.viewport,RectTransformUtility.WorldToScreenPoint(null,point))){var guide=GameObject.Find("StoryShowTarget");if(guide==null){canvasRenderer.SetAlpha(0);return;}point=guide.transform.position;}
   rest=((RectTransform)transform.parent).InverseTransformPoint(point);bool reduced=s.Workshop.reducedMotion||!s.Settings.effects;float bounce=reduced?0:Mathf.Max(0,Mathf.Sin(Time.unscaledTime*Mathf.PI*2/1.25f))*5;rectTransform.localPosition=new Vector3(Mathf.Round(rest.x+10),Mathf.Round(rest.y-18+bounce),0);canvasRenderer.SetAlpha(1);transform.SetAsLastSibling();
  }
  // The project's own TypeScript TutorialFinger pixel silhouette, rendered as crisp horizontal pixel runs.
  static readonly Vector2[] Outer={new Vector2(8,0),new Vector2(16,0),new Vector2(16,16),new Vector2(28,16),new Vector2(28,20),new Vector2(32,20),new Vector2(32,36),new Vector2(28,36),new Vector2(28,40),new Vector2(12,40),new Vector2(12,36),new Vector2(8,36),new Vector2(8,32),new Vector2(4,32),new Vector2(4,28),new Vector2(0,28),new Vector2(0,16),new Vector2(8,16)};
  static readonly Vector2[] Inner={new Vector2(10,2),new Vector2(14,2),new Vector2(14,22),new Vector2(18,22),new Vector2(18,18),new Vector2(22,18),new Vector2(22,22),new Vector2(26,22),new Vector2(26,24),new Vector2(30,24),new Vector2(30,34),new Vector2(26,34),new Vector2(26,38),new Vector2(14,38),new Vector2(14,34),new Vector2(10,34),new Vector2(10,30),new Vector2(6,30),new Vector2(6,26),new Vector2(2,26),new Vector2(2,18),new Vector2(6,18),new Vector2(6,22),new Vector2(10,22)};
  static bool Inside(Vector2[] p,float x,float y){bool yes=false;for(int i=0,j=p.Length-1;i<p.Length;j=i++)if((p[i].y>y)!=(p[j].y>y)&&x<(p[j].x-p[i].x)*(y-p[i].y)/(p[j].y-p[i].y)+p[i].x)yes=!yes;return yes;}
  protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();var r=rectTransform.rect;for(int y=0;y<40;y++)for(int x=0;x<32;x++){if(!Inside(Outer,x+.5f,y+.5f))continue;Color tint=Inside(Inner,x+.5f,y+.5f)?GameTheme.Hex("F8E4B3"):GameTheme.Hex("122236");if((x>=14&&x<18&&y>=26&&y<34)||(x>=22&&x<26&&y>=24&&y<34))tint=GameTheme.Hex("CB9472");int n=vh.currentVertCount;float a=r.x+x*r.width/32,b=r.y+(39-y)*r.height/40,w=r.width/32,h=r.height/40;vh.AddVert(new Vector3(a,b),tint,Vector2.zero);vh.AddVert(new Vector3(a+w,b),tint,Vector2.zero);vh.AddVert(new Vector3(a+w,b+h),tint,Vector2.zero);vh.AddVert(new Vector3(a,b+h),tint,Vector2.zero);vh.AddTriangle(n,n+1,n+2);vh.AddTriangle(n,n+2,n+3);}}
 }
}
